ui['delete-dialog'].addEventListener('close', async () => { if (ui['delete-dialog'].returnValue !== 'confirm' || !pendingDelete) { pendingDelete = null; return; } const target = pendingDelete; pendingDelete = null; if (target.type === 'session') { await deleteSegments(target.value.id); await deleteScreenshots(target.value.id); await removeSession(target.value.id); if (!session) { segments = []; renderTranscript(); } await renderSavedSessions(); setSessionStatus('Saved transcript deleted from this browser.'); return; } if (target.type === 'ocr') { const cache = await caches.open('local-browser-transcriber-ocr-v1'); await Promise.all(OCR_ASSETS.map((path) => cache.delete(new URL(path, document.baseURI).href))); localStorage.removeItem('localBrowserTranscriberOcrEnabled'); setOcrToggle(false); await renderDownloadedModels(); return; } const model = target.value; const cache = await caches.open('transformers-cache'); const keys = await cache.keys(); await Promise.all(keys.filter((request) => request.url.includes(model.repo)).map((request) => cache.delete(request))); await removeModel(model.id); if (activeModel === model.id) activeModel = null; await renderModels({ rebuild: true }); await renderDownloadedModels(); refreshDiagnostics(); });

function download(content, name, type) { const link = document.createElement('a'); link.href = URL.createObjectURL(content instanceof Blob ? content : new Blob([content], { type })); link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 1000); }
function clock(ms) { const seconds = Math.floor(ms / 1000); return `${String(Math.floor(seconds / 3600)).padStart(2, '0')}:${String(Math.floor(seconds / 60) % 60).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`; }
function fileSafeName(name) { return name.replaceAll(/[^a-z0-9._-]+/gi, '-').replaceAll(/^-|-$/g, '') || 'transcript'; }
function transcriptProvenance() { const model = findModel(activeModel || selectedModel); return { app: 'Local Browser Transcriber', website: 'https://projects.timdixon.net/Local-Call-Transcriber/', model: model?.name || 'Not recorded', language: selectedLanguage || 'Not recorded', audioProcessing: audioProcessingEnabled ? 'On' : 'Off', voiceSettings: { ...voiceProcessing } }; }
