function renderTranscriptProvenance() { let summary = $('transcript-provenance'); if (!summary) { summary = document.createElement('p'); summary.id = 'transcript-provenance'; summary.className = 'transcript-provenance'; $('transcript-heading').after(summary); } summary.textContent = `${transcriptProvenance().model} · ${selectedLanguage || 'English'} · Audio processing ${audioProcessingEnabled ? 'on' : 'off'} · Generated with Local Browser Transcriber`; }
function exportText(items = segments) { return `${provenanceText()}\n\nTranscript\n${items.map((segment) => `${formatDateTime(segment.start)} | ${sourceName(segment.source)} | ${segment.text}`).join('\n')}`; }
function currentSessionId() { return session?.id || segments.find((segment) => segment.sessionId)?.sessionId; }
